class Solution {
    int m, n;
    vector<vector<int>> g;
    int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};

    void dfs(int i, int j, vector<vector<bool>>& vis,
             vector<pair<int,int>>& cells, vector<vector<int>>& mark,
             int stamp, int& walls, vector<pair<int,int>>& front) {
        vis[i][j] = true;
        cells.push_back({i, j});
        for (int d = 0; d < 4; d++) {
            int x = i + dx[d], y = j + dy[d];
            if (x < 0 || x >= m || y < 0 || y >= n) continue;
            if (g[x][y] == 0) {
                walls++;
                if (mark[x][y] != stamp) {
                    mark[x][y] = stamp;
                    front.push_back({x, y});
                }
            } else if (g[x][y] == 1 && !vis[x][y]) {
                dfs(x, y, vis, cells, mark, stamp, walls, front);
            }
        }
    }

public:
    int containVirus(vector<vector<int>>& isInfected) {
        g = isInfected;
        m = g.size();
        n = g[0].size();
        vector<vector<int>> mark(m, vector<int>(n, 0));
        int stamp = 0, ans = 0;
        while (true) {
            vector<vector<bool>> vis(m, vector<bool>(n, false));
            vector<vector<pair<int,int>>> regs, fronts;
            vector<int> wl;
            for (int i = 0; i < m; i++)
                for (int j = 0; j < n; j++)
                    if (g[i][j] == 1 && !vis[i][j]) {
                        stamp++;
                        vector<pair<int,int>> cells, front;
                        int walls = 0;
                        dfs(i, j, vis, cells, mark, stamp, walls, front);
                        regs.push_back(move(cells));
                        fronts.push_back(move(front));
                        wl.push_back(walls);
                    }
            int best = 0, bi = -1;
            for (int r = 0; r < (int)regs.size(); r++)
                if ((int)fronts[r].size() > best) {
                    best = fronts[r].size();
                    bi = r;
                }
            if (bi < 0 || best == 0) break;
            ans += wl[bi];
            for (auto& p : regs[bi]) g[p.first][p.second] = 2;
            for (int r = 0; r < (int)regs.size(); r++)
                if (r != bi)
                    for (auto& p : fronts[r]) g[p.first][p.second] = 1;
        }
        return ans;
    }
};
